  'F-03 · SQL-injectie in het loginformulier':
      'F-03 · SQL injekcija prisijungimo formoje',
  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?': 'Siųsti šį vaizdą DI modeliui?',
  'De afbeelding gaat ongewijzigd naar': 'Vaizdas bus išsiųstas nepakeistas į',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck vaizde nieko nepaslepia: veidai, tekstas ekrano kopijoje ir matomi duomenys išsiunčiami kartu.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Vaizdų patikra čia aptiko vieną ar daugiau atpažįstamų veidų.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Šalia eksporto sukuriami du failai, kuriais gavėjas gali patikrinti redagavimus.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'išvardija, kas praleista, be pačių reikšmių. Šį failą galima siųsti kartu su ataskaita.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'turi raktus, kuriais kiekvieną paslėptą reikšmę galima atkurti. Nesiųskite šio failo kartu: tada redagavimas panaikinamas. Laikykite jį prie šaltinio.',
  'slides': 'skaidrės',
  'Achtergehouden': 'Sulaikyta',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Sulaikyta: klasifikuota griežčiau nei pristatymas',
  '1 slide achtergehouden door haar TLP': '1 skaidrė sulaikyta dėl jos TLP',
  'slides achtergehouden door hun TLP': 'skaidrės sulaikytos dėl jų TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Šios skaidrės neįtraukiamos pristatant, eksportuojant ar į paketą. Padidinkite pristatymo TLP lygį skiltyje Pristatymo informacija, kad jos būtų įtrauktos.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Visos skaidrės sulaikytos dėl jų TLP klasifikacijos — nėra ką rodyti.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Visos skaidrės sulaikytos dėl jų TLP klasifikacijos — nėra ką eksportuoti.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Visos skaidrės praleistos arba sulaikytos dėl jų TLP klasifikacijos — nėra ką rodyti.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Visos skaidrės praleistos arba sulaikytos dėl jų TLP klasifikacijos — nėra ką eksportuoti.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Diagramų skaičiai neįrašyti — jie liko tik šiame lange:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Naršyklėje nėra atkūrimo po strigties: uždarius šį skirtuką, neįrašytas darbas dings. Išsaugokite pristatymą patys.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Vietinė CVE duomenų bazė (atsisiuntimą pradedate patys): OciDeck paima masinius duomenis per api.github.com ir leidimo failą, į kurį tas adresas nurodo.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE paieška (numatytai išjungta): kai ji įjungta, jūsų paieškos žodis keliauja į nustatytą CVE veidrodį, o jei ten nieko nerandama – į ENISA Europos duomenų bazę ir į MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Įterptas YouTube arba Vimeo vaizdo įrašas įkelia grotuvą iš tos paslaugos.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Naršyklėje: jei naršyklė atsisako paimti adresą tiesiogiai, OciDeck bando dar kartą per serverį, iš kurio atkeliavo programa; tada tas adresas pasiekia tą serverį.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Atšaukimas nebuvo išsaugotas. Kitą kartą paleidus jūsų sutikimas vėl galios.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Skyriaus antraštė, skelbianti naują pristatymo dalį. Laikykite ją trumpą. Pridėkite fono vaizdą iš vaizdų bibliotekos.',
  'Bronnen doorzoeken…': 'Ieškoma šaltiniuose…',
  'Niet doorzocht': 'Neieškota',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Ši patikra neveikia žiniatinklio versijoje: veidų aptikimui reikia sistemos bibliotekos, kurios naršyklė neturi. Naudokite darbalaukio versiją, kad patikrintumėte veidus paveikslėliuose.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Prieigos raktui reikia repozitorijaus skaitymo ir rašymo teisių. Gitea ir Forgejo neturi paieškos serveryje; OciDeck ieško vietoje.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Prieigos raktui reikia repo srities (arba detaliai: Contents skaityti ir rašyti).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Prieigos raktui reikia read_repository, write_repository ir read_api. Paieškai serveryje reikia Advanced arba Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Greita paieška serveryje — dėl indeksavimo vėlavimo ką tik pakeista kaladė gali būti praleista.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Medija neišsaugoma paprastame .md faile',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Šiame skirtuke pasirinkti vaizdai, vaizdo ir garso įrašai egzistuoja tik atmintyje. Paprastas .md failas jų neišsaugo — atvėrus iš naujo jų nebebus. Eksportuokite kaip .ocideck paketą, kad pasiimtumėte mediją su savimi.',
  'Media verwijderd om privacyredenen':
      'Medija pašalinta dėl privatumo priežasčių',
  'Afbeeldingen door AI laten taggen?': 'Leisti DI pažymėti šiuos vaizdus?',
