  'creditcardnummer': 'kredito kortelės numeris',
  'beveiligingscode van een creditcard': 'kortelės saugos kodas (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'duomenys pranešėjo pastabose — skaidrėje nematomi, bet patenka į eksportą',
  'Certificaat vertrouwen?': 'Pasitikėti šiuo sertifikatu?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Šio serverio sertifikato nepasirašė pripažintas išdavėjas. Savarankiškai talpinamam serveriui tai normalu, bet lygiai taip atrodo ir perimtas ryšys.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Palyginkite žemiau esantį kontrolinį kodą su tuo, kurį rodo jūsų serveris. Jei sutampa, kalbatės su tinkama mašina.',
  'Uitgegeven aan': 'Išduota',
  'Uitgegeven door': 'Išdavė',
  'Geldig tot': 'Galioja iki',
  'Vingerafdruk (SHA-256)': 'Kontrolinis kodas (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Pasitikima tik šiuo vienu sertifikatu. Jei serveris jį vėliau pakeis, OciDeck paklaus dar kartą.',
  'Vertrouwen': 'Pasitikėti',
  'Certificaat bekijken': 'Peržiūrėti sertifikatą',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Vietos, kur laikai ir ieškai savo pristatymų — aplankai šiame kompiuteryje, WebDAV serveriai, S3 kaušai ir git saugyklos pramaišiui. Vilk juos norima tvarka: viršutinis kiekvienos rūšies laikomas numatytuoju.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3 saugykla: kai prisijungi prie kaušo, išsaugomi galinis taškas, kaušo pavadinimas ir tavo prieigos raktas (slaptasis raktas saugiai tavo sistemos raktinėje), o pristatymai, kuriuos atidarai ar išsaugai, siunčiami į tą saugyklos paslaugą.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git saugykla: kai prisijungi prie saugyklos, išsaugomas tavo prieigos žetonas (saugiai tavo sistemos raktinėje), o pristatymai, kuriuos išsaugai, siunčiami į tą serverį kaip commitai. Darbinė saugyklos kopija lieka nešifruota šiame įrenginyje.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Šios pateikties kalbai trūksta ligų pavadinimų. Religija, politinės pažiūros ir profsąjungų terminai atpažįstami, o šablonai su kontroliniu skaitmeniu (asmens kodas, IBAN, pasas) veikia visada — bet nesitikėkite, kad bus rasta diagnozė.',
  'niet getest': 'nepatikrinta',
  'Werkte op': 'Veikė',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Esate prisijungę, bet čia neturite prieigos. Slaptažodis nėra problema — paprašykite administratoriaus teisių į šį aplanką.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Jūsų raktas galioja, bet tam neturi teisių. Suteikite jam daugiau teisių arba palaukite, jei forge taiko ribojimą.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Raktas galioja, bet tam neturi teisių — suteikite jam daugiau teisių saugyklai.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Prisijungta, bet prieigos nėra — slaptažodis nėra problema. Paprašykite teisių į šį aplanką.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Tai atrodo kaip pilnas DAV URL. Su Nextcloud OciDeck šį kelią išveda pats — čia turi būti tik serveris.',
  'Overnemen': 'Taikyti',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV nėra (tinkamai) nustatytas — patikrinkite serverio duomenis skiltyje Nustatymai → Saugykla.',
